command:
// The bayonet is granted (and equipped) automatically when you gain Fix Bayonets!;
// this button just makes sure it's equipped and reminds you of the timing.
const showGenericCard = game.pirateborg.api.showGenericCard;
const bayonet = actor.items.find((i) => i.type === "weapon" && (i.name === "Bayonets" || i.name === "Bayonet"));
if (bayonet && !bayonet.system.equipped) {
  await bayonet.update({ "system.equipped": true });
}
await showGenericCard({
  actor,
  title: item.name,
  description: bayonet
    ? `Your bayonet (${bayonet.system.damageDie}) is fixed and equipped. You can attack with it on the same turn you reload a black-powder weapon.`
    : `You can attack with your bayonet on the same turn you reload a black-powder weapon.`,
});
